apiVersion: v1
kind: ConfigMap
metadata:
  name: error-pages-nginx
  namespace: {{ .Namespace }}
data:
  # nginx opens each page on each request, so an edited page needs no restart.
  nginx.conf: |
    worker_processes 1;
    pid /tmp/nginx.pid;
    error_log /dev/stderr warn;
    events {
        worker_connections 256;
    }
    http {
        include /etc/nginx/mime.types;
        default_type application/octet-stream;
        charset utf-8;
        server_tokens off;
        access_log off;
        client_body_temp_path /tmp/client_temp;
        proxy_temp_path /tmp/proxy_temp;
        fastcgi_temp_path /tmp/fastcgi_temp;
        uwsgi_temp_path /tmp/uwsgi_temp;
        scgi_temp_path /tmp/scgi_temp;
        root /usr/share/nginx/html;
        server {
            listen 8080;
            location = /healthz {
                default_type text/plain;
                return 200 "ok\n";
            }
        }
        server {
            listen 8081;
            add_header Cache-Control "no-store" always;
            error_page 404 503 =503 /maintenance.html;
            location / {
                return 503;
            }
            location = /maintenance.html {
                internal;
            }
        }
    }
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: error-pages
  namespace: {{ .Namespace }}
spec:
  replicas: 1
  revisionHistoryLimit: 3
  selector:
    matchLabels: {app.kubernetes.io/name: error-pages}
  strategy:
    type: RollingUpdate
    rollingUpdate: {maxSurge: 1, maxUnavailable: 0}
  template:
    metadata:
      labels: {app.kubernetes.io/name: error-pages, templates.zeabur.com/template: error-pages}
    spec:
      automountServiceAccountToken: false
      securityContext:
        runAsNonRoot: true
        runAsUser: 101
        runAsGroup: 101
        seccompProfile: {type: RuntimeDefault}
      containers:
        - name: nginx
          image: docker.io/nginxinc/nginx-unprivileged:1.31.7-alpine-slim@sha256:a8cb0f33d51fa107c96fd2bd3a71aaf564ec131e9d2bdf8700944f0ed8b170d7
          command: [nginx]
          args: [-g, 'daemon off;']
          ports:
            - {name: pages, containerPort: 8080}
            - {name: maintenance, containerPort: 8081}
          securityContext:
            runAsNonRoot: true
            allowPrivilegeEscalation: false
            readOnlyRootFilesystem: true
            capabilities: {drop: [ALL]}
          resources:
            requests: {cpu: 5m, memory: 8Mi}
            limits: {cpu: 100m, memory: 32Mi}
          readinessProbe:
            httpGet: {path: /healthz, port: pages}
            periodSeconds: 5
          livenessProbe:
            httpGet: {path: /healthz, port: pages}
            periodSeconds: 10
          volumeMounts:
            - {name: pages, mountPath: /usr/share/nginx/html, readOnly: true}
            - {name: config, mountPath: /etc/nginx/nginx.conf, subPath: nginx.conf, readOnly: true}
            - {name: tmp, mountPath: /tmp}
      volumes:
        - name: pages
          configMap: {name: error-pages}
        - name: config
          configMap: {name: error-pages-nginx}
        - name: tmp
          emptyDir: {medium: Memory, sizeLimit: 8Mi}
---
apiVersion: v1
kind: Service
metadata:
  name: error-pages
  namespace: {{ .Namespace }}
  labels:
    # Zeabur OSS sends maintenance and error pages to the Service with this label.
    zeabur.com/page-server: "true"
spec:
  selector: {app.kubernetes.io/name: error-pages}
  ports:
    - {name: pages, port: 8080, targetPort: pages, appProtocol: http}
    - {name: maintenance, port: 8081, targetPort: maintenance, appProtocol: http}
